UPDATE ds_chat_session
SET user_id = #{userId}, connection_id = #{connectionId}, title = #{title},
    revision = #{revision}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND id = #{id}

UPDATE ds_chat_message
SET user_id = #{userId}, role = #{role}, parts_json = #{partsJson},
    metadata_json = #{metadataJson}, sequence = #{sequence}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND session_id = #{sessionId} AND id = #{id}

